INSERT INTO projects (title_en,title_ar,slug,section_id,status_id,featured_order,visibility,thumbnail,hero_image,short_description_en,short_description_ar,my_role_en,my_role_ar,company_en,company_ar,duration_en,duration_ar,team_size,contribution_percentage,user_count,performance_score,completion_percentage,display_order,project_url,github_url,description_en,description_ar,problem_en,problem_ar,solution_en,solution_ar,architecture_en,architecture_ar,challenges_en,challenges_ar,lessons_learned_en,lessons_learned_ar) SELECT 'PitchProof','بيتش بروف','pitchproof','1','1','2','published','/assets/images/projects/pitchproof.webp','/assets/images/projects/pitchproof-hero.webp','AI-assisted PR briefing tool that refuses to treat model output as truth.','أداة ذكاء اصطناعي لتجهيز البيانات الصحفية ترفض اعتبار مخرجات النموذج حقيقة.','Sole developer','مطور منفرد','','','2026','2026','1','100','0','0','100','100','','https://github.com/Oelsayed99/pitchproof','PitchProof guides a PR consultant through a structured six-step brief for a product launch or funding announcement, checks every answer for meaning and evidence, exposes the claims that could be repeated publicly, requires human approval, and generates pitches from approved facts only.','يرشد بيتش بروف مستشار العلاقات العامة عبر نموذج من ست خطوات لإطلاق منتج أو إعلان تمويل، ويراجع كل إجابة من حيث المعنى والدليل، ويعرض الادعاءات القابلة للنشر، ويشترط موافقة بشرية، ثم يولّد العروض من الحقائق المعتمدة فقط.','Generic AI writing tools turn a thin announcement into fluent but unsupported copy. For PR, a confident sentence that isn''t true is worse than no sentence.','تحوّل أدوات الكتابة بالذكاء الاصطناعي الإعلانات الضعيفة إلى نصوص سلسة لكن بلا سند. وفي العلاقات العامة، الجملة الواثقة غير الصحيحة أسوأ من عدم وجودها.','Deterministic preflight rules check completeness, Gemini reviews every answer and extracts a claim inventory, a human approves, edits or rejects each claim, and three story angles and pitches are generated from approved claim IDs only.','قواعد فحص مسبقة تتحقق من الاكتمال، ثم يراجع Gemini كل إجابة ويستخرج قائمة الادعاءات، ويوافق شخص على كل ادعاء أو يعدّله أو يرفضه، ثم تُولَّد ثلاث زوايا وعروض من معرّفات الادعاءات المعتمدة فقط.','Next-compatible TypeScript app with server-side API routes for review and generation; API keys never reach the browser. Zod validates every model response, and a deterministic demo mode gives reliable presentations without calling the model.','تطبيق TypeScript بمسارات API على الخادم للمراجعة والتوليد، ولا تصل مفاتيح API إلى المتصفح. يتحقق Zod من كل استجابة للنموذج، ويوفر وضع العرض الثابت عروضًا موثوقة دون استدعاء النموذج.','Enforcing grounding in code rather than in the prompt: every generated sentence must reference an approved claim ID, and a single unknown or rejected reference rejects the whole response. Provider failures reveal no partial output.','فرض الالتزام بالمصادر في الكود لا في التعليمات: كل جملة مولدة يجب أن تشير إلى معرّف ادعاء معتمد، وأي إشارة غير معروفة أو مرفوضة ترفض الاستجابة كاملة. ولا تُعرض أي مخرجات جزئية عند فشل المزود.','Model output is untrusted input. Treating it with the same validation as user input, and making the verification boundary visible to the user, is what makes an AI tool safe to rely on.','مخرجات النموذج مدخلات غير موثوقة. التعامل معها بنفس التحقق المطبق على مدخلات المستخدم، وجعل حدود التحقق واضحة له، هو ما يجعل أداة الذكاء الاصطناعي جديرة بالاعتماد.' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='pitchproof');
