INSERT INTO projects (title_en,title_ar,slug,section_id,status_id,featured_order,visibility,thumbnail,hero_image,short_description_en,short_description_ar,my_role_en,my_role_ar,company_en,company_ar,duration_en,duration_ar,team_size,contribution_percentage,user_count,performance_score,completion_percentage,display_order,project_url,github_url,description_en,description_ar,problem_en,problem_ar,solution_en,solution_ar,architecture_en,architecture_ar,challenges_en,challenges_ar,lessons_learned_en,lessons_learned_ar) SELECT 'SeroEvents Platform','منصة SeroEvents','seroevents-platform','1','2','3','published','/assets/images/projects/seroevents-platform.webp','/assets/images/projects/seroevents-platform-hero.webp','Bilingual website and event platform for healthcare and scientific conferences in the UAE.','موقع ومنصة فعاليات ثنائية اللغة للمؤتمرات الطبية والعلمية في الإمارات.','Tech Lead','قائد تقني','SeroEvents UAE','SeroEvents الإمارات','2026 – present','2026 – الآن','1','100','0','0','60','101','https://seroevents.com','','As Tech Lead at SeroEvents UAE I''m rebuilding the company''s website into an event platform: bilingual English and Arabic, with the public event catalogue migrated from the original site.','بصفتي القائد التقني في SeroEvents الإمارات، أعيد بناء موقع الشركة ليصبح منصة فعاليات ثنائية اللغة بالعربية والإنجليزية، مع نقل كتالوج الفعاليات العامة من الموقع السابق.','','','','','Next.js 15 (App Router) with PostgreSQL through Prisma, Microsoft Graph for transactional email, and file storage kept alongside the database for backups. Runs behind a reverse proxy in production.','Next.js 15 مع PostgreSQL عبر Prisma، وMicrosoft Graph للبريد الإلكتروني، وتخزين الملفات بجانب قاعدة البيانات للنسخ الاحتياطي، ويعمل خلف Reverse Proxy في الإنتاج.','','','','' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='seroevents-platform');
