INSERT INTO projects (title_en,title_ar,slug,section_id,status_id,featured_order,visibility,thumbnail,hero_image,short_description_en,short_description_ar,my_role_en,my_role_ar,company_en,company_ar,duration_en,duration_ar,team_size,contribution_percentage,user_count,performance_score,completion_percentage,display_order,project_url,github_url,description_en,description_ar,problem_en,problem_ar,solution_en,solution_ar,architecture_en,architecture_ar,challenges_en,challenges_ar,lessons_learned_en,lessons_learned_ar) SELECT 'In-App Translation System','نظام الترجمة داخل التطبيق','kas-translation-system','2','1',NULL,'published','/assets/images/projects/kas-translation-system.webp','/assets/images/projects/kas-translation-system-hero.webp','Translate a hosting platform in place: inline editing, msgid storage, translation states and history.','ترجمة منصة استضافة في مكانها: تحرير مباشر وتخزين بالمعرفات وحالات الترجمة وسجلها.','Architecture, frontend and backend endpoints','المعمارية والواجهة ونقاط الخادم','ALL-INKL.COM','ALL-INKL.COM','2024 – 2026','2024 – 2026','1','100','0','0','100','102','','','Tooling that lets translators work directly inside the ALL-INKL platform instead of editing code: iframe-based inline editing, msgid storage, per-string states (new, ongoing, done, checked), attribute translation, per-page status, history and comments.','أداة تتيح للمترجمين العمل داخل منصة ALL-INKL مباشرة دون تعديل الكود: تحرير داخل iframe، وتخزين بالمعرفات، وحالات لكل نص (جديد، قيد العمل، منجز، تمت مراجعته)، وترجمة السمات، وحالة لكل صفحة، وسجل وتعليقات.','Platform content had to be translated and maintained across languages, and translators needed context without touching source code.','كان لا بد من ترجمة محتوى المنصة وصيانته بعدة لغات، واحتاج المترجمون إلى السياق دون لمس الكود.','','','','','Cross-origin constraints between the editor and the framed pages, translating attributes such as title, tooltip and placeholder, and accessibility issues like aria-hidden warnings.','قيود المصادر المختلفة بين المحرر والصفحات المضمنة، وترجمة السمات مثل العنوان والتلميح والنص المؤقت، ومشكلات الوصولية مثل تحذيرات aria-hidden.','','' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='kas-translation-system');
