INSERT INTO projects (title_en,title_ar,slug,section_id,status_id,featured_order,visibility,thumbnail,hero_image,short_description_en,short_description_ar,my_role_en,my_role_ar,company_en,company_ar,duration_en,duration_ar,team_size,contribution_percentage,user_count,performance_score,completion_percentage,display_order,project_url,github_url,description_en,description_ar,problem_en,problem_ar,solution_en,solution_ar,architecture_en,architecture_ar,challenges_en,challenges_ar,lessons_learned_en,lessons_learned_ar) SELECT 'Browser CCTV Viewer','عارض كاميرات المراقبة','cctv-browser-viewer','2','1',NULL,'published','/assets/images/projects/cctv-browser-viewer.webp','/assets/images/projects/cctv-browser-viewer-hero.webp','Live and recorded RTSP camera feeds across offices, viewable in an ordinary browser.','بث مباشر ومسجل لكاميرات RTSP في المكاتب عبر متصفح عادي.','Browser interface and integration','واجهة المتصفح والتكامل','ALL-INKL.COM','ALL-INKL.COM','2025','2025','1','100','0','0','100','103','','','A browser interface over an RTSPtoWeb streaming service: single, 1×2, 2×2 and 3×3 camera matrices, live view, playback with a seek bar, office tabs and camera mapping, with JWT-protected access.','واجهة متصفح فوق خدمة بث RTSPtoWeb: شبكات عرض للكاميرات بأحجام مختلفة، وعرض مباشر، وتشغيل مع شريط تقديم، وتبويبات للمكاتب، وربط للكاميرات، مع وصول محمي بـ JWT.','','','','','','','RTSP port conflicts, limits on concurrent streams, and Safari-specific playback failures over MSE/WebSocket.','تعارض منافذ RTSP، وحدود البث المتزامن، ومشكلات تشغيل خاصة بمتصفح Safari عبر MSE وWebSocket.','','' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='cctv-browser-viewer');
