INSERT INTO projects (title_en,title_ar,slug,section_id,status_id,featured_order,visibility,thumbnail,hero_image,short_description_en,short_description_ar,my_role_en,my_role_ar,company_en,company_ar,duration_en,duration_ar,team_size,contribution_percentage,user_count,performance_score,completion_percentage,display_order,project_url,github_url,description_en,description_ar,problem_en,problem_ar,solution_en,solution_ar,architecture_en,architecture_ar,challenges_en,challenges_ar,lessons_learned_en,lessons_learned_ar) SELECT 'Lead Generation Agent','وكيل توليد العملاء','n8n-lead-agent','5','2',NULL,'published','/assets/images/projects/n8n-lead-agent.webp','/assets/images/projects/n8n-lead-agent-hero.webp','Multi-workflow automation on self-hosted n8n that finds leads. Outreach and content generation are next.','أتمتة متعددة المسارات على n8n مستضاف ذاتيًا تبحث عن العملاء المحتملين. التواصل وإنشاء المحتوى هما الخطوة التالية.','Sole developer','مطور منفرد','','','2026 – present','2026 – الآن','1','100','0','0','40','105','','','Multi-workflow automation on self-hosted n8n that finds leads. Outreach and content generation are next.','أتمتة متعددة المسارات على n8n مستضاف ذاتيًا تبحث عن العملاء المحتملين. التواصل وإنشاء المحتوى هما الخطوة التالية.','','','','','','','','','','' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='n8n-lead-agent');
