INSERT INTO projects (title_en,title_ar,slug,section_id,status_id,featured_order,visibility,thumbnail,hero_image,short_description_en,short_description_ar,my_role_en,my_role_ar,company_en,company_ar,duration_en,duration_ar,team_size,contribution_percentage,user_count,performance_score,completion_percentage,display_order,project_url,github_url,description_en,description_ar,problem_en,problem_ar,solution_en,solution_ar,architecture_en,architecture_ar,challenges_en,challenges_ar,lessons_learned_en,lessons_learned_ar) SELECT 'This Portfolio & CMS','هذا الموقع ونظام إدارته','portfolio-cms','4','2',NULL,'published','/assets/images/projects/portfolio-cms.webp','/assets/images/projects/portfolio-cms-hero.webp','A hand-written PHP MVC framework with a bilingual, database-backed CMS and inline editing.','إطار MVC مكتوب يدويًا بلغة PHP مع نظام إدارة محتوى ثنائي اللغة وتحرير مباشر.','Design and development','التصميم والتطوير','','','2025 – present','2025 – الآن','1','100','0','0','85','106','https://elsayedomar.com','https://github.com/Oelsayed99/portfolio-update','Router, controllers, models and views written from scratch. Case studies are composed from ordered sections with many-to-many technology and tag relationships, and all copy lives in the database so it can change without a deploy. Dockerised, with separate development and production stacks.','الموجّه والمتحكمات والنماذج والواجهات مكتوبة من الصفر. تتكون دراسات الحالة من أقسام مرتبة مع علاقات بالتقنيات والوسوم، وكل النصوص في قاعدة البيانات لتتغير دون نشر جديد. يعمل في Docker مع بيئتين للتطوير والإنتاج.','','','','','','','','','','' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug='portfolio-cms');
